using System;using System.IO;using System.Linq;using System.Security.Principal;
using P=UsbHidAdmissionPolicy;using Store=SentinelHidAdmission.UsbExactBlockFileStore;
internal static class UsbHidLinkedStoreQualification {
 const string A=@"USB\VID_0002&PID_0001\SYNTHETIC_A",B=@"USB\VID_0003&PID_0001\SYNTHETIC_B",Internal=@"USB\VID_0001&PID_0001\SYNTHETIC_INTERNAL";static string nonce,path;static int checks;
 static void Check(bool value){if(!value)throw new InvalidOperationException("linked_store_qualification_refused");checks++;}
 static void Refuse(Action a){bool rejected=false;try{a();}catch{rejected=true;}Check(rejected);}
 sealed class Proxy:UsbHidPnpFileJournal.ICommittedDisableLedger {internal Func<string,string,bool> Read;public bool OwnsDisabled(string id,string tree){if(Read==null)throw new InvalidOperationException("ledger_unbound");return Read(id,tree);}}
 sealed class ModeledPnp:UsbHidPnpTransaction.IPnp {
  internal readonly System.Collections.Generic.Dictionary<string,bool> Disabled=new System.Collections.Generic.Dictionary<string,bool>();
  public UsbHidSetupApi.Node Read(UsbHidSetupApi.Plan p){bool off;Disabled.TryGetValue(p.Instance,out off);return new UsbHidSetupApi.Node(p.Instance,"HIDClass",new[]{@"USB\Class_03"},true,off?0u:8u,off?22u:0u,new UsbHidSetupApi.Node[0]);}
  public UsbHidSetupApi.Result Change(UsbHidSetupApi.Plan p,bool enable,Action fence){fence();Disabled[p.Instance]=!enable;return new UsbHidSetupApi.Result("Pending verification",0,enable?8u:0u,enable?0u:22u,false);}
 }
 static P.Request Request(P.Snapshot before,string action,string[] approvals,string[] targets){DateTime now=DateTime.UtcNow;return new P.Request(action,before,new P.Snapshot(before.Generation+1,before.OwnerSid,action=="activate"||action!="deactivate"&&before.Active,before.InternalSafety,approvals,before.ReceiptDigest),targets,Guid.NewGuid().ToString("N"),new string('b',64),now,now.AddMinutes(5));}
 static void Open(P.Snapshot current,P.Transition pending,Action fence,Action<UsbHidParentCommitLinks,UsbHidPnpFileJournal> action){var proxy=new Proxy();using(var journal=UsbHidPnpFileJournal.OpenPrivate(nonce,fence,proxy))using(var links=UsbHidParentCommitLinks.OpenPrivate(nonce,fence,()=>new UsbHidParentCommitLinks.View(current,pending),journal.Load)){var source=links.Source(pending!=null&&pending.Request.Action=="allow"&&P.Same(current,pending.Request.Before)?pending.Request.Digest:null);proxy.Read=(id,tree)=>new UsbHidCommittedDisableLedger(source,fence).OwnsDisabled(id,tree);action(links,journal);}}
 static void Commit(Store store,P.Request q,ModeledPnp native,bool loseReply){store.WritePrepared(q);store.AdvancePending(q.Digest,P.Stage.Prepared,P.Stage.RecoveryArmed);if(q.Action=="block"||q.Action=="allow")store.WithWriterFence(q,false,fence=>{var pending=new P.Transition(q,P.Stage.RecoveryArmed);Open(q.Before,pending,fence,(links,journal)=>{var plans=q.Targets.Select(id=>{var node=native.Read(new UsbHidSetupApi.Plan(id,q.TopologyHash,"unused"));return new UsbHidSetupApi.Plan(id,q.TopologyHash,UsbHidSetupApi.TreeBinding(node),node.Status,node.Problem,node.Disableable,"synthetic-connector",UsbHidSetupApi.RecoveryTreeBinding(node));}).ToArray();new UsbHidPnpTransaction(journal,native).Apply(q.Digest,q.Action,plans,fence);});});store.AdvancePending(q.Digest,P.Stage.RecoveryArmed,P.Stage.Applied);store.AdvancePending(q.Digest,P.Stage.Applied,P.Stage.PolicyVerified);
  store.BeforeLinkedCommit=(request,current,pending,fence)=>Open(current,pending,fence,(links,journal)=>{var pnp=request.Action=="block"||request.Action=="allow"?journal.Load(request.Digest):null;links.PublishBeforeCommit(request,pnp==null?null:pnp.Digest,pnp==null?null:pnp.Binding);});
  store.CommitCandidate(q.Digest,q.Before,q.After);Check(P.Same(store.ReadCommitted(),q.After));if(loseReply)return;Reconcile(store,q,native);
 }
 static void Reconcile(Store store,P.Request q,ModeledPnp native){store.BeforeLinkedRetirement=(request,current,pending,fence)=>Open(current,pending,fence,(links,journal)=>{if(P.Same(current,request.After))links.ReconcileCommitted(request,(d,a,plans)=>new UsbHidPnpTransaction(journal,native).Commit(d,a,plans,fence));else{Check(P.Same(current,request.Before));var state=journal.Load(request.Digest);Check(state==null||state.Phase=="Recovered pending physical verification");}});store.WithLinkedReadFence((current,pending,fence)=>Open(current,pending,fence,(links,journal)=>links.ReconcileCommitted(q,(d,a,plans)=>new UsbHidPnpTransaction(journal,native).Commit(d,a,plans,fence))));store.AdvancePending(q.Digest,P.Stage.PolicyVerified,P.Stage.Committed);store.RetirePending(q.Digest);Check(store.ReadPending()==null);}
 static bool Own(Store store,string id){bool result=false;store.WithLinkedReadFence((current,pending,fence)=>Open(current,pending,fence,(links,journal)=>result=new UsbHidCommittedDisableLedger(links.Source(),fence).OwnsDisabled(id,UsbHidSetupApi.TreeBinding(new ModeledPnp().Read(new UsbHidSetupApi.Plan(id,new string('b',64),"unused"))))));return result;}
 [STAThread]public static int Main(string[] args){if(args.Length!=1||args[0]!="--protected-private-linked")return 2;if(!new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator))return 3;int stage=1;try{
  nonce=Guid.NewGuid().ToString("N");string root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),"SentinelHidLinkedStoreQualification");SentinelPolicyDirectory.Provision(root);path=Path.Combine(root,nonce);SentinelPolicyDirectory.Provision(path);foreach(string name in new[]{"SentinelHidParentLinksQualification","SentinelHidPnpJournalQualification"}){string parent=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),name);SentinelPolicyDirectory.Provision(parent);SentinelPolicyDirectory.Provision(Path.Combine(parent,nonce));}
  var native=new ModeledPnp();P.Request blockA;
  using(var store=new Store(path)){store.InitializeInactive(new P.Snapshot(1,WindowsIdentity.GetCurrent().User.Value,false,new[]{Internal},new string[0],new string('a',64)));var initial=store.ReadCommitted();Check(!initial.Active);stage=2;var activate=Request(initial,"activate",new string[0],new string[0]);Commit(store,activate,native,false);var allowA=Request(activate.After,"allow",new[]{A},new[]{A});Commit(store,allowA,native,false);var allowB=Request(allowA.After,"allow",new[]{A,B},new[]{B});Commit(store,allowB,native,false);stage=3;blockA=Request(allowB.After,"block",new[]{B},new[]{A});Commit(store,blockA,native,true);Check(native.Disabled[A]);Refuse(()=>Own(store,A));}
  // Fresh store instance emulates the reply-loss/process-boundary window. The
  // parent state and Applied PnP record come from actual protected files.
  using(var store=new Store(path)){stage=4;Check(P.Same(store.ReadCommitted(),blockA.After));Reconcile(store,blockA,native);Check(Own(store,A));var blockB=Request(blockA.After,"block",new string[0],new[]{B});Commit(store,blockB,native,false);Check(Own(store,A)&&Own(store,B));stage=5;var releaseA=Request(blockB.After,"allow",new[]{A},new[]{A});Commit(store,releaseA,native,false);Check(!Own(store,A)&&Own(store,B));Check(!native.Disabled[A]&&native.Disabled[B]);
   stage=6;var request=Request(releaseA.After,"block",new string[0],new[]{A});store.WritePrepared(request);store.AdvancePending(request.Digest,P.Stage.Prepared,P.Stage.RecoveryArmed);store.AdvancePending(request.Digest,P.Stage.RecoveryArmed,P.Stage.Applied);store.AdvancePending(request.Digest,P.Stage.Applied,P.Stage.PolicyVerified);store.BeforeLinkedCommit=null;Refuse(()=>store.CommitCandidate(request.Digest,request.Before,request.After));Check(P.Same(store.ReadCommitted(),request.Before));
  }
  Console.WriteLine("PASS "+checks+" actual protected parent store/link/PnP file assertions: activate, approvals A/B, lost parent reply reconciliation, selected Allow preserves B, missing-hook refusal; native PnP modeled; NO GPO/device/input claim");return 0;
 }catch(Exception error){Console.WriteLine("FAIL protected linked fixture stage "+stage+" "+error.GetType().Name+" "+error.HResult.ToString("X8")+" site "+(error.TargetSite==null?"none":error.TargetSite.Name));return 1;}}
}
